@layer components {
  :where([data-control-family="switch"][data-slot="root"]) {
    --cui-switch-inline-size: calc(var(--spacing) * 9);
    --cui-switch-height: calc(var(--spacing) * 5);
    --cui-switch-padding: calc(var(--spacing) * 0.5);
    --cui-switch-thumb-inline-size: calc(var(--spacing) * 4);
    --cui-switch-thumb-press-scale: 1.25 1;
    --cui-switch-thumb-backdrop-filter: none;
    --_switch-direction: 1;
    --_switch-progress: 0;
    --_switch-travel: calc(var(--cui-switch-inline-size) - var(--cui-switch-padding) * 2 - var(--cui-switch-thumb-inline-size));
    block-size: var(--cui-switch-height);
    inline-size: var(--cui-switch-inline-size);
    padding: var(--cui-switch-padding);
    touch-action: pan-y;
    user-select: none;
    --cui-switch-background: oklch(from var(--foreground) l c h / 0.14);
    --cui-switch-hover-background: oklch(from var(--foreground) l c h / 0.2);
    --cui-switch-checked-background: var(--primary);
    --cui-switch-checked-hover-background: oklch(from var(--primary) l c h / 0.9);
    --cui-switch-thumb-radius: 9999px;
    --cui-switch-thumb-background: var(--background);
    --cui-switch-thumb-shadow: var(--shadow-sm);
    border-radius: calc(infinity * 1px);
    background: var(--cui-switch-background);
    outline: none;
    transition: background-color var(--duration-base) var(--ease-standard);
  }

  :where([data-control-family="switch"][data-slot="root"]:hover) {
    background: var(--cui-switch-hover-background);
  }

  :where([data-control-family="switch"][data-slot="root"]:active) {
    --cui-switch-background: oklch(from var(--foreground) l c h / 0.25);
    background: var(--cui-switch-background);
  }

  :where([data-control-family="switch"][data-slot="root"][data-checked]) {
    --_switch-progress: 1;
    background: var(--cui-switch-checked-background);
  }

  :where([data-control-family="switch"][data-slot="root"][data-checked]:hover) {
    background: var(--cui-switch-checked-hover-background);
  }

  :where([data-control-family="switch"][data-slot="root"][data-checked]:active) {
    --cui-switch-checked-background: oklch(from var(--primary) l c h / 0.8);
    background: var(--cui-switch-checked-background);
  }

  :where([data-control-family="switch"][data-slot="root"][data-disabled]) {
    opacity: 0.5;
  }

  :where([data-control-family="switch"][data-slot="root"][data-disabled]:hover) {
    background: var(--cui-switch-background);
  }

  :where([data-control-family="switch"][data-slot="root"][data-disabled][data-checked]:hover) {
    background: var(--cui-switch-checked-background);
  }

  :where([data-control-family="switch"][data-slot="thumb"]) {
    border-radius: var(--cui-switch-thumb-radius);
    background: var(--cui-switch-thumb-background);
    box-shadow: var(--cui-switch-thumb-shadow);
    inline-size: var(--cui-switch-thumb-inline-size);
    block-size: calc(var(--cui-switch-height) - var(--cui-switch-padding) * 2);
    translate: calc(var(--_switch-direction) * var(--_switch-travel) * var(--_switch-progress)) 0;
    transform-origin: left center;
    -webkit-backdrop-filter: var(--cui-switch-thumb-backdrop-filter);
    backdrop-filter: var(--cui-switch-thumb-backdrop-filter);
    transition-property: translate, scale, background-color, box-shadow;
    transition-duration: var(--duration-base);
    transition-timing-function: var(--ease-emphasized);
  }

  :where([data-control-family="switch"][data-slot="root"][data-disabled] [data-slot="thumb"]) {
    opacity: 0.8;
  }

  :where([data-control-family="switch"][data-slot="thumb-icon"]) {
    color: oklch(from var(--foreground) l c h / 0.7);
    transition-property: color, opacity;
    transition-duration: var(--duration-base);
    transition-timing-function: var(--ease-standard);
  }

  :where([data-control-family="switch"][data-slot="root"][data-checked] [data-slot="thumb-icon"]:not([data-switch-icon="unchecked"])) {
    color: var(--primary-text);
  }

  :where([data-control-family="switch"][data-slot="thumb-icon"][data-switch-icon="unchecked"]) {
    color: oklch(from var(--foreground) l c h / 0.6);
    opacity: 1;
  }

  :where([data-control-family="switch"][data-slot="root"][data-checked] [data-switch-icon="unchecked"]) {
    opacity: 0;
  }

  :where([data-control-family="switch"][data-slot="thumb-icon"][data-switch-icon="checked"]) {
    color: var(--primary-text);
    opacity: 0;
  }

  :where([data-control-family="switch"][data-slot="root"][data-checked] [data-switch-icon="checked"]) {
    opacity: 1;
  }

  :where([data-control-family="switch"][data-slot="root"]:dir(rtl)) {
    --_switch-direction: -1;
  }

  :where([data-control-family="switch"][data-slot="thumb"][data-checked]),
  :where([data-control-family="switch"][data-slot="thumb"]:dir(rtl)) {
    transform-origin: right center;
  }

  :where([data-control-family="switch"][data-slot="thumb"][data-checked]:dir(rtl)) {
    transform-origin: left center;
  }

  :where(
    [data-control-family="switch"][data-slot="root"]:is(:active, [data-dragging]):not([data-disabled], [data-readonly]) [data-slot="thumb"]
  ) {
    scale: var(--cui-switch-thumb-press-scale);
  }

  :where([data-control-family="switch"][data-slot="root"][data-dragging]) {
    --_switch-progress: var(--_switch-drag-progress);
  }

  :where([data-control-family="switch"][data-slot="root"][data-drag-checked="false"]) {
    background: var(--cui-switch-background);
  }

  :where([data-control-family="switch"][data-slot="root"][data-drag-checked="true"]) {
    background: var(--cui-switch-checked-background);
  }

  :where([data-control-family="switch"][data-slot="root"][data-dragging] [data-slot="thumb"]) {
    transition-property: scale, background-color, box-shadow;
  }
}

@property --cui-switch-thumb-shadow {
  syntax: "*";
  inherits: true;
